CREATE USER 'teacher'@'localhost'
  IDENTIFIED BY 'T@2026';
CREATE USER 'guest'@'%' IDENTIFIED BY 'G@2026';
GRANT SELECT, INSERT, UPDATE(grade)
  ON db_school.sc TO 'teacher'@'localhost'
  WITH GRANT OPTION;
GRANT SELECT ON db_school.* TO 'guest'@'%';
SHOW GRANTS FOR 'teacher'@'localhost';
REVOKE ALL PRIVILEGES, GRANT OPTION
  FROM 'guest'@'%';
DROP USER 'guest'@'%';
